mapper.select:
SELECT a.member_id AS "memberId", m.name AS "name", NVL(a.status, 0) AS "status",
    TO_CHAR(a.created_at, 'YYYY-MM-DD HH24:MI') AS "createdAt"
FROM share_participant a JOIN member m ON m.member_id = a.member_id
WHERE a.share_id = #{id}
AND a.member_id = #{member}
ORDER BY a.created_at, a.member_id
